using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class GhostAudit {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_DeskAndCollision/"));static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string original=SceneManager.GetActiveScene().path;var rows=new List<object>();var seen=new HashSet<string>();Scene temp=default;try{foreach(string f in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Circular.unity");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).Where(t=>t.gameObject.activeInHierarchy&&t.GetComponents<Collider>().Length==1&&t.GetComponent<BoxCollider>()&&t.GetComponent<MeshFilter>()).ToArray();temp=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);var ps=temp.GetPhysicsScene();var hits=new Collider[8];foreach(var t in ts){var bc=t.GetComponent<BoxCollider>();var mf=t.GetComponent<MeshFilter>();var mesh=mf.sharedMesh;string asset=AssetDatabase.GetAssetPath(mesh);if(!asset.Contains("/Props/")||!seen.Add(asset)||!bc.enabled||bc.isTrigger||bc.size.y<1.5f)continue;var g=new GameObject("VisualMeshProbe"){hideFlags=HideFlags.HideAndDontSave};SceneManager.MoveGameObjectToScene(g,temp);var mc=g.AddComponent<MeshCollider>();mc.sharedMesh=mesh;g.transform.position=new Vector3(0,10000,0);Physics.SyncTransforms();int total=0;var ghost=new List<float[]>();var b=new Bounds(bc.center,bc.size);for(float x=b.min.x-.20f;x<=b.max.x+.20f;x+=.15f)for(float z=b.min.z-.20f;z<=b.max.z+.20f;z+=.15f){var p=new Vector3(x,.95f,z);float dx=Mathf.Max(b.min.x-x,0,x-b.max.x),dz=Mathf.Max(b.min.z-z,0,z-b.max.z);if(dx*dx+dz*dz>.27f*.27f||b.max.y<.32f)continue;total++;if(ps.OverlapCapsule(new Vector3(x,10000.38f,z),new Vector3(x,10001.48f,z),.28f,hits,~0,QueryTriggerInteraction.Ignore)==0)ghost.Add(V(new Vector3(x,0,z)));}rows.Add(new{floor=f,asset,example=t.name,boxCenter=V(bc.center),boxSize=V(bc.size),samples=total,empty=ghost.Count,points=ghost});UnityEngine.Object.DestroyImmediate(g);}EditorSceneManager.CloseScene(temp,true);temp=default;}}finally{if(temp.IsValid())EditorSceneManager.CloseScene(temp,true);EditorSceneManager.OpenScene(original);}File.WriteAllText(H+"ghost_candidates.json",JsonConvert.SerializeObject(rows,Formatting.Indented));return new{models=rows.Count,candidates=rows.Where(r=>(int)r.GetType().GetProperty("empty").GetValue(r)>3).Select(r=>new{asset=r.GetType().GetProperty("asset").GetValue(r),samples=r.GetType().GetProperty("samples").GetValue(r),empty=r.GetType().GetProperty("empty").GetValue(r)})};}
}
